{
  "name": "Yoctopuce通用传感器接口",
  "name_en": "Yoctopuce Generic Sensor Interface",
  "manufacturer": "Yoctopuce",
  "description": "这是一个面向 Yoctopuce 各类传感器的通用软件接口，而不是单一实体仪器。它用于统一读取传感器测量值、单位、原始值、最小/最大值，配置记录频率与定时上报，访问历史数据，并管理校准点与数据记录功能，适合在实验系统中对不同 Yoctopuce 传感器进行通用接入。",
  "description_en": "This is a generic software interface for Yoctopuce sensors rather than a single physical instrument. It is used to read sensor values, units, raw values, minimum/maximum values, configure logging and timed reporting, access recorded data, and manage calibration points and data logging across different Yoctopuce sensor types in laboratory setups.",
  "actions": [
    {
      "action_name": "auto-set_lowestValue",
      "description": "设置记录的最小值",
      "description_en": "set the recorded minimum value"
    },
    {
      "action_name": "auto-set_highestValue",
      "description": "设置记录的最大值",
      "description_en": "set the recorded maximum value"
    },
    {
      "action_name": "auto-set_logFrequency",
      "description": "设置数据记录频率",
      "description_en": "set the data logging frequency"
    },
    {
      "action_name": "auto-set_reportFrequency",
      "description": "设置定时上报频率",
      "description_en": "set the timed report frequency"
    },
    {
      "action_name": "auto-set_advMode",
      "description": "设置上报值的测量模式",
      "description_en": "set the measurement mode for the advertised value"
    },
    {
      "action_name": "auto-set_calibrationParam",
      "description": "设置校准参数",
      "description_en": "set the calibration parameters"
    },
    {
      "action_name": "auto-set_resolution",
      "description": "设置测量分辨率",
      "description_en": "set the measurement resolution"
    },
    {
      "action_name": "auto-isSensorReady",
      "description": "检查传感器是否可提供最新测量值",
      "description_en": "check whether the sensor can provide an up-to-date measurement"
    },
    {
      "action_name": "auto-startDataLogger",
      "description": "启动数据记录器",
      "description_en": "start the data logger"
    },
    {
      "action_name": "auto-stopDataLogger",
      "description": "停止数据记录器",
      "description_en": "stop the data logger"
    },
    {
      "action_name": "auto-registerTimedReportCallback",
      "description": "注册定时测量上报回调",
      "description_en": "register a timed measurement report callback"
    },
    {
      "action_name": "auto-calibrateFromPoints",
      "description": "根据校准点定义误差校正",
      "description_en": "define error correction from calibration points"
    },
    {
      "action_name": "auto-loadCalibrationPoints",
      "description": "加载已定义的校准点",
      "description_en": "load previously defined calibration points"
    },
    {
      "action_name": "auto-nextSensor",
      "description": "枚举下一个可访问的传感器",
      "description_en": "enumerate the next accessible sensor"
    }
  ],
  "tag_hints": [
    "Yoctopuce sensors",
    "generic sensor interface",
    "sensor data logging",
    "timed measurement reports",
    "sensor calibration",
    "historical measurement data"
  ]
}

